PrintWriter out = new PrintWriter(client.getOutputStream(), true);
       CommandBuilder builder = new CommandBuilder(out);
while(run) {
        String line = d.readLine();
        if(line == null) break;
        String prefix = line.substring(0, 4);
        String msg    = line.substring(5);
        switch(msg) {
        case START: builder.newCmd(prefix); break;
        case STOP:  builder.endCmd(prefix).execute();
                   out.println(RETURN);
                   break;
        default:    builder.addArg(prefix, msg); break;
        }
       }
} catch (IOException e) { }
}
};

